package com.hiretrack.entity;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="interviews")public class Interview{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="application_id")private JobApplication application;private String roundName;private LocalDateTime interviewDate;private String interviewType;@Column(length=1000)private String meetingLink;@Column(length=3000)private String notes;public Long getId(){return id;}public JobApplication getApplication(){return application;}public void setApplication(JobApplication v){application=v;}public String getRoundName(){return roundName;}public void setRoundName(String v){roundName=v;}public LocalDateTime getInterviewDate(){return interviewDate;}public void setInterviewDate(LocalDateTime v){interviewDate=v;}public String getInterviewType(){return interviewType;}public void setInterviewType(String v){interviewType=v;}public String getMeetingLink(){return meetingLink;}public void setMeetingLink(String v){meetingLink=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}}